import { useQueryClient } from '@tanstack/react-query';
import type { ShopperBasketsV2Types } from 'commerce-sdk-isomorphic';
import { useShopperBasketsV2Mutation as useShopperBasketsMutation } from '@salesforce/commerce-sdk-react';
import { getMaxOrderQuantity } from 'app/utils/maxOrderQuantity';

/**
 * The minimal basket shape this hook needs, regardless of which caller supplies it: the
 * post-auth callback (`useWishlistAuthDrawer.ts`, wired in this step) passes the resolved value
 * of its own `mergeBasket` mutation directly; the cart drawer's render guard
 * (`overrides/app/pages/cart/cartDrawerContainer.tsx`, step 4.6 — not yet built) will pass its
 * own `useCurrentBasket()` data. `Pick`-narrowed, matching `cartItemMapper.ts`'s own established
 * pattern for taking an untyped-at-the-edges SDK response and narrowing it to only the fields a
 * pure function actually reads, rather than depending on the exact generic SDK response type
 * either caller's own mutation/query hook happens to produce.
 */
export type CartCapBasket = Pick<ShopperBasketsV2Types.Basket, 'basketId' | 'lastModified' | 'productItems'>;

/**
 * Outcome of one `capBasketQuantities` call. A discriminated union (typescript.md's guidance for
 * variant/state modelling) rather than a boolean-plus-optional-error: each branch is something a
 * caller could reasonably want to react to differently, and no AC or copy exists yet for any of
 * them (that is `useCartMessages`, step 4.3, not built) — this file only reports what happened,
 * it does not decide what the shopper sees.
 */
export type CartCapResult =
  | { status: 'not-needed' }
  | { status: 'skipped'; reason: 'mutation-in-flight' | 'already-attempted-this-version' }
  | { status: 'corrected' }
  | { status: 'error'; error: unknown };

/**
 * `getMaxOrderQuantity` is typed for a SCAPI product response (`id: string` required — see
 * `overrides/app/utils/maxOrderQuantity.ts`). A basket line item has no `id` field at all: only
 * `itemId`/`productId` (confirmed against the generated `BasketProductItem` type — verified via
 * a throwaway `tsc` repro that assigning a same-shaped object to a type requiring `id` fails
